func contactSourceLabel(ctx context.Context, source string, isManual bool, accounts []models.Account) string {
	if isManual {
		return i18n.T(ctx, "contacts.origin.manual")
	}
	if strings.HasPrefix(source, "synced:") {
		accountID := strings.TrimPrefix(source, "synced:")
		for _, account := range accounts {
			if account.ID == accountID {
				return i18n.T(ctx, "contacts.origin.imported_from", "source", accountContactOriginLabel(ctx, account))
			}
		}
		return i18n.T(ctx, "contacts.origin.imported_account")
	}
	if bookID, ok := strings.CutPrefix(source, "book:"); ok {
		for _, account := range accounts {
			for _, book := range account.ContactAddressBooks {
				if book.ID == bookID {
					return i18n.T(ctx, "contacts.origin.imported_from", "source", accountContactOriginLabel(ctx, account)+" / "+contactAddressBookDisplayName(ctx, book))
				}
			}
		}
		return i18n.T(ctx, "contacts.origin.imported_book")
	}
	switch source {
	case "observed":
		return i18n.T(ctx, "contacts.origin.observed")
	case "manual":
		return i18n.T(ctx, "contacts.origin.manual")
	case models.ContactOriginImported:
		return i18n.T(ctx, "contacts.origin.imported_file")
	case "synced":
		return i18n.T(ctx, "contacts.origin.imported_any")
	case "provider:gmail":
		return i18n.T(ctx, "contacts.origin.imported_from", "source", "Gmail")
	case "provider:outlook":
		return i18n.T(ctx, "contacts.origin.imported_from", "source", "Outlook")
	default:
		if source == "" {
			return i18n.T(ctx, "contacts.origin.local")
		}
		return strings.Title(source)
	}
}

func contactSaveTargetValue(account models.Account) string {
	return "account:" + account.ID
}

func contactBookTargetValue(book models.ContactAddressBook) string {
	return "book:" + book.ID
}

func accountContactSyncCapable(account models.Account) bool {
	return account.ContactSyncEnabled
}

// contactInitialSyncPlaces lists the accounts and address books a saved
// contact syncs with, for the editor to warn before one taken out loses its
// copy.
func contactInitialSyncPlaces(contact *models.Contact) string {
	if contact == nil || strings.TrimSpace(contact.ID) == "" {
		return ""
	}
	var places []string
	for _, target := range contact.SaveTargets {
		if target != "local" && target != contactHome(contact) {
			places = append(places, target)
		}
	}
	return strings.Join(places, ",")
}

// contactSaveTargetSelected says whether target is among a contact's Gofer
// Sync places. Its home never is: the contact is there already, and a new
// contact starts with none.
func contactSaveTargetSelected(contact *models.Contact, target string) bool {
	if contact == nil || strings.TrimSpace(contact.ID) == "" || target == contactHome(contact) {
		return false
	}
	for _, selected := range contact.SaveTargets {
		if selected == target {
			return true
		}
	}
	return false
}

func accountContactSaveLabel(account models.Account) string {
	name := strings.TrimSpace(account.Name)
	email := strings.TrimSpace(account.Email)
	if name == "" {
		return email
	}
	if email == "" || strings.EqualFold(name, email) {
		return name
	}
	return fmt.Sprintf("%s <%s>", name, email)
}

func accountContactOriginLabel(ctx context.Context, account models.Account) string {
	name := strings.TrimSpace(account.Name)
	if name != "" {
		return name
	}
	if email := strings.TrimSpace(account.Email); email != "" {
		return email
	}
	return i18n.T(ctx, "contacts.origin.account")
}

func contactViewMode(mode string) string {
	if mode == "table" {
		return "table"
	}
	return "cards"
}

func contactViewIndicatorStyle(mode string) string {
	if contactViewMode(mode) == "table" {
		return "transform:translateX(calc(100% + 2px))"
	}
	return "transform:translateX(0)"
}

// contactFiltersActiveExcept says whether a filter other than the contacts
// to resolve, or a search, narrows the list.
func contactFiltersActiveExcept(filters models.ContactFilters) bool {
	return filters.Source != "" || filters.StoredIn != "" || filters.SaveTarget != "" || filters.Activity != "" || strings.TrimSpace(filters.Query) != ""
}

// contactFiltersActiveCount is how many filters the Filters button counts.
func contactFiltersActiveCount(filters models.ContactFilters) int {
	count := 0
	for _, value := range []string{filters.Source, filters.StoredIn, filters.SaveTarget, filters.Activity} {
		if value != "" {
			count++
		}
	}
	if filters.Unresolved {
		count++
	}
	return count
}

// contactOrigin is how the list shows where a contact lives.
type contactOrigin struct {
	Label string
	Title string
	// Color is the account's, for a contact living on one.
	Color string
}

// contactCardHome names where a contact lives, its Stored in: Gofer Local,
// or the account, with its color, and the address book in the title.
func contactCardHome(ctx context.Context, contact models.Contact, accounts []models.Account) contactOrigin {
	home := strings.TrimSpace(contact.StoredIn)
	if home == "" || home == "local" {
		label := i18n.T(ctx, "contacts.origin.local")
		return contactOrigin{Label: label, Title: i18n.T(ctx, "contacts.stored_in_title", "place", label)}
	}
	for _, account := range accounts {
		if home == "account:"+account.ID {
			label := accountContactOriginLabel(ctx, account)
			return contactOrigin{Label: label, Title: i18n.T(ctx, "contacts.stored_in_title", "place", label), Color: account.Color}
		}
		for _, book := range account.ContactAddressBooks {
			if home == "book:"+book.ID {
				label := accountContactOriginLabel(ctx, account)
				return contactOrigin{Label: label, Title: i18n.T(ctx, "contacts.stored_in_title", "place", label+" / "+contactAddressBookDisplayName(ctx, book)), Color: account.Color}
			}
		}
	}
	label := i18n.T(ctx, "contacts.origin.unavailable_account")
	return contactOrigin{Label: label, Title: label}
}

// contactListDate is a date a contact's card or row shows: the date alone
// (Date, for the table, under its column's name), saying what it is (Text,
// for the card) and in full (Title).
type contactListDate struct {
	Date  string
	Text  string
	Title string
}

// contactInteractionDate is the Interaction field: when the contact was last
// in mail, or, in the Trash, when it was moved there.
func contactInteractionDate(ctx context.Context, contact models.Contact) contactListDate {
	if trashed := strings.TrimSpace(contact.TrashedAt); trashed != "" {
		return contactListDate{Date: trashed, Text: i18n.T(ctx, "contacts.card.trashed_on", "date", trashed), Title: i18n.T(ctx, "contacts.card.trashed", "date", trashed, "purge", contact.TrashPurgeAt)}
	}
	return contactDatedAs(ctx, "contacts.card.last_mail_on", contact.LastSeenAt)
}

// contactCardLayoutSampleDate is the layout editor's sample card's date, days
// from today, as the list writes dates.
func contactCardLayoutSampleDate(ctx context.Context, days int) string {
	return i18n.Dates(ctx).Date(time.Now().AddDate(0, 0, days))
}

// contactDatedAs is date said with key ("Created on {date}"), or nothing
// without a date.
func contactDatedAs(ctx context.Context, key, date string) contactListDate {
	date = strings.TrimSpace(date)
	if date == "" {
		return contactListDate{}
	}
	text := i18n.T(ctx, key, "date", date)
	return contactListDate{Date: date, Text: text, Title: text}
}

